<!--  the agent graph view (like the graph view): the agent graph SVG, generated by the service itself
      (with all texts escaped), with its statistics overlaid onto the top-right corner of its border  -->
<template>
    <div v-show="view === 'flow'" id="fframe">
        <!-- eslint-disable vue/no-v-html -->
        <div id="flow" ref="flowEl" :class="{ panning: pan !== null }" @click="flowClick" @dblclick="flowClick"
            @wheel="flowZoom" @pointerdown="flowPanStart" @pointermove="flowPanMove" @pointerup="pan = null" @pointercancel="pan = null"
            v-html="flow"></div>
        <!-- eslint-enable vue/no-v-html -->
        <div v-if="flowStats !== null" class="gstats">{{ flowStats.agents }} agents, {{ flowStats.states }} states</div>
    </div>
</template>

<script setup lang="ts">
import { ref, nextTick, watch, onMounted, onBeforeUnmount } from "vue"
import { view, flow, flowStats, flowSel, flowEl, task, showFlowAgent, raiseEdges } from "./ase-task-board-web-client-model"

/*  the panning of the agent graph (by dragging its background), and its zoom factor  */
const pan  = ref<{ x: number, y: number, left: number, top: number } | null>(null)
let   zoom = 1

/*  select the clicked agent card (resp. state), and on a double click onto an
    agent card show the agents view with its (first) agent selected  */
const flowClick = (ev: MouseEvent) => {
    const node = (ev.target as Element).closest<SVGGElement>("g.node[data-id]")
    if (node === null)
        return
    flowSel.value = node.dataset.id!
    if (ev.type === "dblclick")
        showFlowAgent(node.dataset.id!)
}

/*  size the agent graph by the zoom factor (its natural size being its view box)  */
const applyZoom = () => {
    const svg = flowEl.value?.querySelector("svg")
    if (svg === null || svg === undefined)
        return
    const box = svg.viewBox.baseVal
    svg.setAttribute("width",  String(box.width  * zoom))
    svg.setAttribute("height", String(box.height * zoom))
}

/*  zoom the agent graph by a factor, keeping the given point (or the center of the view) in place  */
const zoomBy = (factor: number, x?: number, y?: number) => {
    const el  = flowEl.value
    const svg = el?.querySelector("svg")
    if (el === null || el === undefined || svg === null || svg === undefined)
        return
    const port = el.getBoundingClientRect()
    const cx   = x ?? port.left + port.width  / 2
    const cy   = y ?? port.top  + port.height / 2
    const old  = svg.getBoundingClientRect()
    const rx   = (cx - old.left) / old.width
    const ry   = (cy - old.top)  / old.height
    zoom = Math.min(4, Math.max(0.1, zoom * factor))
    applyZoom()
    const now = svg.getBoundingClientRect()
    el.scrollLeft += now.left + rx * now.width  - cx
    el.scrollTop  += now.top  + ry * now.height - cy
}

/*  zoom the agent graph with the mouse wheel, keeping the point under the pointer in place  */
const flowZoom = (ev: WheelEvent) => {
    ev.preventDefault()
    const delta = ev.deltaY * (ev.deltaMode === WheelEvent.DOM_DELTA_LINE ? 16 : ev.deltaMode === WheelEvent.DOM_DELTA_PAGE ? 400 : 1)
    zoomBy(Math.exp(-delta * 0.002), ev.clientX, ev.clientY)
}

/*  scroll the agent graph by dragging its background with the left mouse button  */
const flowPanStart = (ev: PointerEvent) => {
    const el = flowEl.value
    if (el === null || ev.button !== 0 || (ev.target as Element).closest("g.node") !== null)
        return
    ev.preventDefault()
    el.setPointerCapture(ev.pointerId)
    pan.value = { x: ev.clientX, y: ev.clientY, left: el.scrollLeft, top: el.scrollTop }
}
const flowPanMove = (ev: PointerEvent) => {
    const el = flowEl.value
    if (el === null || pan.value === null)
        return
    el.scrollLeft = pan.value.left - (ev.clientX - pan.value.x)
    el.scrollTop  = pan.value.top  - (ev.clientY - pan.value.y)
}

/*  mark the selected agent card (resp. state) and its edges, and scroll the selection into view, where
    initially (and once the selected node vanished) the first agent card is selected  */
const showSel = () => {
    const nodes = [ ...(flowEl.value?.querySelectorAll<SVGGElement>("g.node[data-id]") ?? []) ]
    if (nodes.length > 0 && !nodes.some((n) => n.dataset.id === flowSel.value))
        flowSel.value = (nodes.find((n) => !n.classList.contains("state")) ?? nodes[0]).dataset.id!
    const id = flowSel.value
    for (const n of nodes)
        (n.querySelector(".acard") ?? n).classList.toggle("sel", n.dataset.id === id)
    raiseEdges(flowEl.value, id)
    if (view.value === "flow")
        flowEl.value?.querySelector(".acard.sel, g.state.sel")?.scrollIntoView({ block: "nearest", inline: "nearest" })
}

/*  follow the selection and a re-rendered agent graph with the zoom and the marks  */
watch([ flowSel, flow, view ], () => {
    nextTick(() => {
        applyZoom()
        showSel()
    })
})

/*  the zoom keys of the agent graph view (not bound via Mousetrap, as its
    single binding per key is already taken by the zoom keys of the graph view)  */
const onZoomKey = (ev: KeyboardEvent) => {
    if (view.value !== "flow" || task.value !== null || ev.target instanceof HTMLInputElement
        || ev.ctrlKey || ev.metaKey || ev.altKey)
        return
    if (ev.key === "0") {
        zoom = 1
        applyZoom()
        showSel()
    }
    else if (ev.key === "+" || ev.key === "=")
        zoomBy(1.25)
    else if (ev.key === "-")
        zoomBy(1 / 1.25)
}
onMounted(() => {
    document.addEventListener("keydown", onZoomKey)
})
onBeforeUnmount(() => {
    document.removeEventListener("keydown", onZoomKey)
})
</script>

